function v152FrameTools(config){
 const sources=new Set(config.sources),managed=new Set(config.managed);
 const post=(source,event,value)=>parent.postMessage({type:'peach-interaction-event',source,event,value},'*');
 document.addEventListener('click',e=>{const block=e.target.closest('[data-v152-block]'),legacy=e.target.closest('[data-main-id]'),source=block?.dataset.v152Block||(!e.target.closest('.v147-node')&&legacy?'object:'+legacy.dataset.mainId:'');if(!source)return;if(e.target.closest('[aria-disabled="true"]')){e.preventDefault();e.stopImmediatePropagation();return;}if(sources.has(source))post(source,'click');if(managed.has(source)){e.preventDefault();e.stopImmediatePropagation();}},true);
 document.addEventListener('scroll',e=>{const port=e.target;if(!port.dataset?.v147Scroll)return;const source='ui:'+port.dataset.v147Owner+'/'+port.dataset.v147Scroll;if(!sources.has(source))return;const horizontal=port.scrollWidth>port.clientWidth&&port.scrollHeight<=port.clientHeight,max=horizontal?port.scrollWidth-port.clientWidth:port.scrollHeight-port.clientHeight;post(source,'scroll',max>0?100*(horizontal?port.scrollLeft:port.scrollTop)/max:0);},true);
 window.addEventListener('message',e=>{if(e.source!==parent||e.data?.type!=='peach-interaction-ui')return;for(const item of e.data.items||[]){const els=item.id.startsWith('block:')?[...document.querySelectorAll('[data-v152-block]')].filter(x=>x.dataset.v152Block===item.id):item.id.startsWith('ui:')&&!item.root?[...document.querySelectorAll('[data-v147-node]')].filter(x=>x.dataset.v147Owner===item.owner&&x.dataset.v147Node===item.node):[...document.querySelectorAll('[data-main-id]')].filter(x=>x.dataset.mainId===item.owner);for(const el of els){if(el.closest('[inert],[data-v221-history]'))continue;if(item.color!==undefined||item.fontSize!==undefined)for(const text of [el,...el.querySelectorAll('strong,span,p,label,button,.text,.v132-value,.v147-text')]){const owner=text.closest('[data-v152-block],[data-v147-node]');if(text!==el&&owner&&owner!==el)continue;if(text.matches('svg,[data-lucide],.icon'))continue;if(item.color!==undefined)text.style.setProperty('color',item.color,'important');if(item.fontSize!==undefined)text.style.setProperty('font-size',item.fontSize+'px','important');}if(item.visible!==undefined)el.style.display=item.visible?'':'none';if(item.opacity!==undefined)el.style.opacity=item.opacity/100;if(item.enabled!==undefined){el.style.pointerEvents=item.enabled?'':'none';el.setAttribute('aria-disabled',String(!item.enabled));}if(item.label!==undefined){const text=el.querySelector('.text');if(text)text.textContent=item.label;}if(item.url){const image=el.querySelector('img');if(image)image.src=item.url;const surface=el.querySelector('.surface');if(surface)surface.style.backgroundImage='url('+JSON.stringify(item.url)+')';}if(item.root)for(const prop of ['x','y','width','height'])if(item[prop]!==undefined)el.style[{x:'left',y:'top',width:'width',height:'height'}[prop]]=item[prop]+(prop==='height'?'px':'%');}}
  if(e.data.panel){const p=e.data.panel;let dialog=document.querySelector('[data-v152-dialog]');if(!dialog){dialog=document.createElement('dialog');dialog.dataset.v152Dialog='';dialog.style.cssText='max-width:92vw;width:420px;padding:16px;background:#282331;color:#eee;border:1px solid #7b607a;border-radius:16px';document.body.append(dialog);}if(!p.opened){dialog.close();return;}dialog.innerHTML='<button data-v152-close style="float:right">关闭</button>'+p.html;dialog.querySelector('[data-v152-close]').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal();}
 });
}

function v237FrameControls(){
 function send(el){const box=el.closest('[data-v147-node]');if(!box||box.closest('[inert],[data-v221-history]'))return;const input=box.querySelector('.v147-input-line input,.v147-input-line textarea');if(!input||input.disabled||input.readOnly)return;parent.postMessage({type:'peach-player-variable237',owner:box.dataset.v147Owner,id:box.dataset.v147Node,value:input.value},'*');}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-v237-submit]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();send(b);},true);
 document.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.isComposing||e.keyCode===229||e.target.tagName==='TEXTAREA'||!e.target.matches('[data-v147-runtime]'))return;const box=e.target.closest('[data-v147-node]');if(!box?.querySelector('[data-v237-submit]'))return;e.preventDefault();e.stopImmediatePropagation();send(e.target);},true);
}

function v150FrameControls(roots){
 const nodes=new Map();for(const r of roots){const walk=n=>{nodes.set(String(r.id)+'/'+n.id,n);(n.children||[]).forEach(walk);};walk(r.node);}
 const post=(el,kind,value)=>parent.postMessage({type:'peach-ui2d-event',kind,owner:el.dataset.v147Owner,id:el.dataset.v147Node||el.dataset.v147Runtime||el.dataset.v147Submit,value},'*');
 const input=e=>{const el=e.target;if(!el.hasAttribute?.('data-v147-runtime'))return;const n=nodes.get(el.dataset.v147Owner+'/'+el.dataset.v147Runtime);if(!n||n.disabled)return;post(el,'input',n.type==='toggle'?el.checked:el.value);};
 document.addEventListener('input',input);document.addEventListener('change',input);
 document.addEventListener('scroll',e=>{const p=e.target;if(!p.dataset?.v147Scroll)return;const key=p.dataset.v147Owner+'/'+p.dataset.v147Scroll;for(const [nodeKey,n]of nodes){if(n.type!=='scrollbar'||n.props.target!==key)continue;const [owner,id]=nodeKey.split('/'),el=[...document.querySelectorAll('[data-v147-runtime]')].find(x=>x.dataset.v147Owner===owner&&x.dataset.v147Runtime===id);if(el){const h=n.props.orientation==='horizontal',max=h?p.scrollWidth-p.clientWidth:p.scrollHeight-p.clientHeight;post(el,'input',max>0?100*(h?p.scrollLeft:p.scrollTop)/max:0);}}},true);
 document.addEventListener('click',e=>{const submit=e.target.closest('[data-v147-submit]');if(submit){post(submit,'submit');return;}const box=e.target.closest('[data-v147-node]');if(!box)return;const n=nodes.get(box.dataset.v147Owner+'/'+box.dataset.v147Node);if(!n||n.disabled||['input','toggle','slider','dropdown','scrollbar'].includes(n.type))return;post(box,'click');});
 for(const [event,kind]of [['focusin','focus'],['focusout','blur']])document.addEventListener(event,e=>{if(e.target.hasAttribute?.('data-v147-runtime'))post(e.target,kind);});document.addEventListener('keydown',e=>{const el=e.target;if(e.key!=='Enter'||e.isComposing||el.tagName==='TEXTAREA'||!el.hasAttribute?.('data-v147-runtime'))return;e.preventDefault();post(el,'submit');});
 window.addEventListener('message',e=>{if(e.source!==parent||e.data?.type!=='peach-ui2d-sync')return;
  for(const item of e.data.items||[]){for(const el of document.querySelectorAll('[data-v147-node]')){if(el.dataset.v147Owner!==item.owner||el.dataset.v147Node!==item.id)continue;if(item.playerFeedback237){const feedback=el.querySelector('[data-v237-feedback]');if(feedback){feedback.textContent=item.playerFeedback237.text;feedback.classList.toggle('is-error',!!item.playerFeedback237.error);}}if(item.progressHTML){const body=el.querySelector(':scope > .v155-body');if(body&&body.outerHTML!==item.progressHTML)body.outerHTML=item.progressHTML;}if(item.style)el.style.cssText=item.style;el.style.display=item.hidden?'none':'';const input=el.querySelector(':scope > input,:scope > select,:scope > .v147-input-line > input,:scope > .v147-input-line > textarea,:scope > .v147-toggle > input');if(input){input.disabled=item.disabled;if(input.type==='checkbox')input.checked=!!item.value;else if(input.type==='range'||input!==document.activeElement)input.value=item.value;}const text=el.querySelector(':scope > .v147-text,:scope > button.v147-button');if(text)text.textContent=item.label;const out=el.querySelector(':scope > .v147-field-label > output');if(out)out.textContent=item.value;const btn=el.querySelector(':scope > button.v147-button');if(btn&&item.active!=null){btn.setAttribute('aria-pressed',item.active);btn.style.boxShadow=item.active?'inset 0 0 0 2px var(--u-accent)':'';}}}
  const cmd=e.data.command;if(cmd?.kind==='v152-render'){const host=[...document.querySelectorAll('.v147-object')].find(el=>el.dataset.mainId===cmd.owner);if(host)host.innerHTML=cmd.html;}if(cmd?.kind==='v152-focus'){const el=[...document.querySelectorAll('[data-v147-runtime]')].find(el=>el.dataset.v147Owner===cmd.owner&&el.dataset.v147Runtime===cmd.id);el?.focus();}if(cmd?.kind==='scroll'){const [owner,id]=cmd.target.split('/');for(const port of document.querySelectorAll('[data-v147-scroll]'))if(port.dataset.v147Owner===owner&&port.dataset.v147Scroll===id){if(cmd.horizontal)port.scrollLeft=(port.scrollWidth-port.clientWidth)*cmd.pct/100;else port.scrollTop=(port.scrollHeight-port.clientHeight)*cmd.pct/100;}}
  if(cmd?.kind==='open'){const el=[...document.querySelectorAll('[data-main-id][data-action]')].find(el=>el.dataset.mainId===cmd.target);el?.click();}
 });parent.postMessage({type:'peach-ui2d-event',kind:'ready'},'*');
}
